  return obiekt;
}
const dane = { id: 1 };
dodajZnacznik(dane);
console.log(dane);
// { id: 1, oznaczony: true } - oryginal ZOSTAL zmutowany, mimo braku "dane = ..."

const licznik = {
  wartosc: 10,
  pokazZOpoznieniem: function () {
    setTimeout(function () {
      console.log(this?.wartosc);
    }, 0);
  },
};
licznik.pokazZOpoznieniem();
// undefined - zwykla funkcja w setTimeout ma wlasne "this", niepowiazane z licznik

function test() {
  const x = "zewnetrzny";
  {
    const x = "wewnetrzny";
    console.log(x);
  }
  console.log(x);
}
test();
// "wewnetrzny"
// "zewnetrzny"

function dzielenie(dzielna, dzielnik) {
  return dzielna / dzielnik;
}
console.log(dzielenie(2, 100));
// 0.02 - poprawny wynik dla dzielenie(2, 100), ale jesli intencja
// byla "100 podzielone przez 2", to argumenty zostaly odwrocone

function test() {
  {
    let wynik = 1;
    console.log(wynik);
  }
  {
    let wynik = 2;
    console.log(wynik);
  }
}
test();
// 1
// 2
// Brak konfliktu - kazdy blok { } ma wlasny, niezalezny zasieg dla let.

console.log("A");
setTimeout(() => console.log("B"), 0);
console.log("C");
// "A"
// "C"
// "B" - mimo opoznienia 0, setTimeout zawsze czeka az caly synchroniczny kod sie skonczy

const produkty = [
  { nazwa: "Ksiazka", cena: 30 },
  { nazwa: "Dlugopis", cena: 5 },
];
console.table(produkty);

console.time("filtrowanie");
const liczby = Array.from({ length: 500000 }, (_, i) => i);
const parzyste = liczby.filter((x) => x % 2 === 0);
console.timeEnd("filtrowanie");
console.log(parzyste.length);
// 250000

function obliczSredniaWazona(oceny, wagi) {
  let suma = 0;
  for (let i = 0; i < oceny.length; i++) {
    suma += oceny[i] * wagi[i];
  }
  // BLAD: powinno byc dzielenie przez sume wag, nie przez oceny.length
  return suma / oceny.length;
}
console.log(obliczSredniaWazona([5, 3], [3, 1]));
// 9 - blednie podzielone przez 2 (dlugosc tablicy) zamiast przez 4 (sume wag [3,1])
// Breakpoint TUZ PRZED "return" pozwolilby zobaczyc, ze suma wag (4)
// rozni sie od oceny.length (2), uzytego blednie w dzieleniu.

function pomnoz(a, b) {
  return a * b;
}
function test() {
  const wynik = pomnoz(3, 4); // step over: pomija wnetrze pomnoz
                              // step into: wchodzi do wnetrza pomnoz
  return wynik;
}
console.log(test());
// 12
// Uzylbym step over, jesli ufam, ze pomnoz dziala poprawnie i interesuje
// mnie tylko wynik. Uzylbym step into, gdybym podejrzewal blad WEWNATRZ
// samej funkcji pomnoz i chcial sledzic jej wykonanie linia po linii.

function sprawdzWarunek(wartosc) {
  debugger;
  if (wartosc > 100) {
    return "duza";
  }
  return "mala";
}
console.log(sprawdzWarunek(150));
// "duza"
// W panelu Variables/Scope w momencie zatrzymania widziałbym dokladna
// wartosc parametru "wartosc" (150) - jeszcze PRZED wykonaniem
// instrukcji if, co pozwala sprawdzic, czy warunek zachowa sie zgodnie
// z oczekiwaniami, zanim zostanie faktycznie wykonany.

// Piec recznie dodanych console.log wymaga z gory ZGADNIECIA, ktore
// dokladnie wartosci beda potrzebne na kazdym z trzech poziomow - czesto
// okazuje sie, ze brakuje jednej istotnej zmiennej i trzeba dopisac
// kolejny console.log, uruchomic kod ponownie i tak w kolko. Jeden
// breakpoint na poczatku najbardziej zewnetrznej funkcji, polaczony ze
// step into na kazdym zagniezdzonym wywolaniu, pokazuje CALY dostepny
// stan (wszystkie zmienne w danym zasiegu) na kazdym poziomie od razu,
// bez koniecznosci przewidywania z gory, co bedzie potrzebne.

function policzZnaki(tekst) {
  return tekst.length + 1;
}
console.log(policzZnaki("kot"));
// 4 - BLAD, powinno byc 3. Wynik "wyglada wiarygodnie" (to nadal
// niewielka liczba), wiec latwo go przeoczyc bez sprawdzenia krok po
// kroku, jaka dokladnie jest wartosc tekst.length przed dodaniem 1.

function filtrujDoroslych(osoby) {
  return osoby.filter((o) => o.wiek > 18);
}
console.log(filtrujDoroslych([{ imie: "Jan", wiek: 18 }, { imie: "Ola", wiek: 20 }]));
// [ { imie: "Ola", wiek: 20 } ] - Jan (dokladnie 18 lat) zostal BLEDNIE odrzucony

const domyslneUstawienia = { motyw: "jasny", jezyk: "pl" };
const wlasneUstawienia = { motyw: "ciemny" };
console.log(Object.assign({}, domyslneUstawienia, wlasneUstawienia));
// { motyw: "ciemny", jezyk: "pl" } - wlasneUstawienia nadpisuje domyslne,
// bo wystepuje jako PozNIEJSZY argument. Odwrocenie kolejnosci dalyby
// { motyw: "jasny", jezyk: "pl" } - po cichu zly wynik, bez zadnego bledu.

// 1. Znajdz linie, od ktorej chcesz zaczac obserwacje (np. poczatek
//    podejrzanej funkcji) i ustaw tam breakpoint (F9 w VS Code lub
//    klikniecie numeru linii w DevTools "Sources").
// 2. Uruchom kod (F5 w VS Code) lub doprowadz do wywolania funkcji w
//    przegladarce - wykonanie zatrzyma sie na breakpoincie.
// 3. Sprawdz aktualne wartosci argumentow/zmiennych w panelu
//    "Variables"/"Scope" - czy sa takie, jakich sie spodziewales?
